#include "towercollision.h"
#include <array>
#include <fstream>
#include <iomanip>
#include <map>
#include <sstream>
#include <iostream>
std::string Float(float value){std::ostringstream text;text<<std::setprecision(9)<<value;std::string out=text.str();if(out.find_first_of(".eE")==std::string::npos)out+=".0";return out+"f";}
int main(int argc,char **argv){if(argc!=3){std::cerr<<"usage: towercollision GAMEDATA OUTPUT_HEADER\n";return 2;}std::vector<towerbake::Model> models;std::string why;if(!towerbake::Load(argv[1],models,why)){std::cerr<<why<<'\n';return 1;}std::ofstream out(argv[2]);if(!out)return 1;
 out<<"#pragma once\n// Generated by tools/bake/towercollision.cpp from original macVC assets.\n#include \"game.h\"\n#include <cstdint>\nnamespace towercollisiondata {\nstruct Triangle {uint16_t v[3];uint8_t surface,piece;};\nstruct Model {int id;const char *name;float bottom;const CVector *vertices;uint16_t vertexCount;const Triangle *triangles;uint16_t triangleCount;};\n";
 for(size_t i=0;i<models.size();++i){std::map<std::array<float,3>,uint16_t> index;std::vector<Vec3f> vertices;std::vector<std::array<uint16_t,3>> faces;
  for(const auto &face:models[i].faces){std::array<uint16_t,3> triangle{};for(int j=0;j<3;++j){auto p=face.v[j];auto [at,added]=index.emplace(std::array<float,3>{p.x,p.y,p.z},uint16_t(vertices.size()));if(added)vertices.push_back(p);triangle[j]=at->second;}faces.push_back(triangle);}
  out<<"inline constexpr CVector kVertices"<<i<<"[]={\n";for(auto p:vertices)out<<"{"<<Float(p.x)<<","<<Float(p.y)<<","<<Float(p.z)<<"},\n";out<<"};\ninline constexpr Triangle kTriangles"<<i<<"[]={\n";
  for(auto f:faces)out<<"{{"<<f[0]<<","<<f[1]<<","<<f[2]<<"},0,0},\n";out<<"};\n";
 }
 out<<"inline constexpr Model kModels[]={\n";for(size_t i=0;i<models.size();++i)out<<"{"<<models[i].id<<",\""<<models[i].name<<"\","<<Float(models[i].bottom)<<",kVertices"<<i<<",uint16_t(sizeof kVertices"<<i<<"/sizeof(CVector)),kTriangles"<<i<<",uint16_t(sizeof kTriangles"<<i<<"/sizeof(Triangle))},\n";out<<"};\n}\n";return out?0:1;
}
